def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md."""
    # Validate arguments
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("width must be an int of at least 1")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")

    paragraphs = text.split('\n')
    result = []

    for para in paragraphs:
        words = para.split()

        if not words:
            result.append("")
            continue

        lines = []
        current_words = []
        is_first_line = True

        for word in words:
            # Determine current line's available width
            if is_first_line:
                indent_str = ""
                available = width
            else:
                indent_str = indent
                available = width - len(indent)

            # Build test line to see if word fits
            if current_words:
                test_line = " ".join(current_words) + " " + word
            else:
                test_line = word

            if len(test_line) <= available:
                # Word fits on current line
                current_words.append(word)
            else:
                # Word doesn't fit on current line
                # Finalize current line if non-empty
                if current_words:
                    lines.append((is_first_line, indent_str, " ".join(current_words)))
                    is_first_line = False
                    current_words = []

                # Add word to new line(s), breaking long words as needed
                remaining = word
                while remaining:
                    # Calculate available width for new line
                    if is_first_line:
                        indent_str = ""
                        available = width
                    else:
                        indent_str = indent
                        available = width - len(indent)

                    if len(remaining) <= available:
                        # Word fits on new line
                        current_words.append(remaining)
                        remaining = ""
                    else:
                        # Word doesn't fit, break it
                        chunk = remaining[:available]
                        lines.append((is_first_line, indent_str, chunk))
                        is_first_line = False
                        remaining = remaining[available:]

        # Finalize last line of paragraph
        if current_words:
            if is_first_line:
                indent_str = ""
            else:
                indent_str = indent
            lines.append((is_first_line, indent_str, " ".join(current_words)))

        # Convert lines to strings with indentation
        for is_first, indent_str, line_text in lines:
            result.append(indent_str + line_text)

    return result
